import { type Project, type Task, measure, taskProgress } from './task-tree.js';

/**
 * A checkable (leaf) task flattened out of the tree, with its ancestry
 * kept as a breadcrumb path so it can be shown in a flat list.
 */
export type FlatTask = {
  task: Task;
  /** titles of ancestors below the grouping root, e.g. ["Networking", "Lobby"] */
  path: string[];
  /** ids of ancestors, top-most first */
  pathIds: string[];
};

/**
 * Flattens a tree into its leaf tasks, keeping breadcrumbs.
 * @param tasks - tree to flatten
 * @param path - prefix path (used for recursion)
 * @param pathIds - prefix ids (used for recursion)
 */
export function flattenLeaves(tasks: Task[], path: string[] = [], pathIds: string[] = []): FlatTask[] {
  const out: FlatTask[] = [];
  tasks.forEach((t) => {
    if (t.subtasks?.length) out.push(...flattenLeaves(t.subtasks, [...path, t.title], [...pathIds, t.id]));
    else out.push({ task: t, path, pathIds });
  });
  return out;
}

/** A top-level area of a project (e.g. "Gun system") with its stats. */
export type Area = {
  task: Task;
  done: number;
  total: number;
  percent: number;
  /** share of the whole project's checkable work, 0..100 */
  weight: number;
  status: 'todo' | 'active' | 'done';
};

/**
 * Builds the list of top-level areas with progress, weight and status.
 * @param project - the project
 */
export function projectAreas(project: Project): Area[] {
  const all = measure(project.tasks).total || 1;
  return project.tasks.map((task) => {
    const p = taskProgress(task);
    return {
      task,
      ...p,
      weight: Math.round((p.total / all) * 100),
      status: p.percent === 100 ? 'done' : p.done > 0 ? 'active' : 'todo',
    };
  });
}

/** A section in the focus frame: one level of grouping inside an area. */
export type Section = { id: string; title: string; description?: string; items: FlatTask[]; done: number; total: number; percent: number };

/**
 * Splits an area into readable sections: its direct leaf tasks first, then one
 * section per sub-group. Anything nested deeper is flattened into its section
 * with a breadcrumb, so the reader never has to scan more than one level.
 * @param area - the top-level task
 */
export function areaSections(area: Task): Section[] {
  const direct = area.subtasks.filter((s) => !s.subtasks?.length);
  const groups = area.subtasks.filter((s) => s.subtasks?.length);
  const sections: Section[] = [];
  if (direct.length) {
    const p = measure(direct);
    sections.push({ id: `${area.id}-direct`, title: groups.length ? 'General' : 'Tasks', items: direct.map((task) => ({ task, path: [], pathIds: [] })), ...p });
  }
  groups.forEach((g) => {
    sections.push({ id: g.id, title: g.title, description: g.description, items: flattenLeaves(g.subtasks, [], []), ...measure(g.subtasks) });
  });
  return sections;
}

/** A leaf task across all projects, for the dashboard's "Up next" list. */
export type NextTask = FlatTask & { project: Project };

/**
 * Returns the next few unchecked tasks per project, preferring areas that
 * are already in progress so momentum is kept.
 * @param projects - all projects
 * @param limit - max items
 */
export function upNext(projects: Project[], limit = 6): NextTask[] {
  const out: NextTask[] = [];
  projects.forEach((project) => {
    const areas = projectAreas(project).sort((a, b) => {
      const rank = (x: Area) => (x.status === 'active' ? 0 : x.status === 'todo' ? 1 : 2);
      return rank(a) - rank(b);
    });
    areas.forEach((a) => {
      const leaves = a.task.subtasks?.length
        ? flattenLeaves(a.task.subtasks, [a.task.title], [a.task.id])
        : [{ task: a.task, path: [], pathIds: [] }];
      leaves.filter((l) => !l.task.done).forEach((l) => out.push({ ...l, project }));
    });
  });
  // interleave projects so one big project does not hide the others
  const byProject = new Map<string, NextTask[]>();
  out.forEach((t) => byProject.set(t.project.id, [...(byProject.get(t.project.id) || []), t]));
  const lists = [...byProject.values()];
  const result: NextTask[] = [];
  for (let i = 0; result.length < limit && lists.some((l) => l[i]); i += 1) {
    lists.forEach((l) => l[i] && result.length < limit && result.push(l[i]));
  }
  return result;
}

/**
 * Finds a task anywhere in a tree.
 * @param tasks - tree
 * @param id - task id
 */
export function findTask(tasks: Task[], id: string): Task | undefined {
  for (const t of tasks) {
    if (t.id === id) return t;
    const found = findTask(t.subtasks || [], id);
    if (found) return found;
  }
  return undefined;
}
